const inItems = $input.all();
// รองรับทั้ง 2 แบบ: (a) 1 item ที่ json เป็น array ทั้งก้อน (b) แยกเป็นคนละ item ต่อ reading
const rows = [];
inItems.forEach((it, idx) => {
  // ต้องใช้ itemMatching ที่นี่ ห้ามใช้ index ตรงๆ — HTTP telemetry node กระจาย array
  // response ออกเป็นหลายร้อย item (1 item ต่อ 1 reading ไม่ใช่ต่อ 1 batch) idx จึงเกิน
  // จำนวน batch เสมอ itemMatching เป็นตัว map แต่ละ reading กลับไปหา batch ต้นทางที่ถูกตัว
  // (เคยพลาดใช้ .all()[idx] แล้วพังทันทีด้วย "Cannot read properties of undefined" 19 ส.ค.)
  const batch = $('Get Active Batches').itemMatching(idx).json;
  const val = it.json;
  const readings = Array.isArray(val) ? val : [val];
  for (const t of readings) {
    if (!t || !t.createdOn) continue;
    rows.push({
      json: {
        device_id: batch.pill_id,
        time_utc: t.createdOn,
        temperature_c: t.temperature,
        gravity_sg: t.gravity != null ? Number((t.gravity / 1000).toFixed(5)) : null,
        gravity_velocity_sg_per_day: t.gravityVelocity,
        battery_percent: t.battery,
        rssi_dbm: t.rssi,
        paired_temp_controller: batch.controller_name
      }
    });
  }
});
return rows;

