const items = $input.all();
const results = [];

// toFixed เพื่อให้เลขทศนิยมแสดงจำนวนหลักคงที่เสมอ (เช่น 20.00 ไม่ใช่ 20)
// ต่างจาก round() ใน Parse AI Response ที่ปัดค่าไว้ใช้ต่อ/insert DB เท่านั้น
function fmt(v, n) {
  return v == null ? '-' : Number(v).toFixed(n);
}

// loop ทุก item (1 item = 1 batch active) — เดิมใช้ $input.first() ตัวเดียว
// ทำให้ตอนมีมากกว่า 1 batch active พร้อมกัน ยิงข้อความให้แค่ batch แรกเท่านั้น
// batch อื่นหายไปเงียบๆ (เจอจริงตอนมี 2 batch active พร้อมกัน)
items.forEach((it) => {
  const d = it.json;
  const sections = [];

  const header = '📋 อัปเดตสถานะ: ' + d.beer_name
    + '\nเฟส: ' + d.detected_phase
    + (d.detected_phase !== d.previous_phase ? (' 🔔 (เปลี่ยนจาก ' + d.previous_phase + ')') : '')
    + (d.next_phase ? (' ใกล้ ' + d.next_phase) : '')
    + (d.pill_is_stale
        ? ('\n⚠️ Pill เงียบมา ' + fmt(d.pill_stale_hours, 1) + ' ชม.'
           + (d.pill_battery_percent != null && Number(d.pill_battery_percent) <= 5 ? ' (แบตหมด)' : '')
           + ' — ค่าด้านล่างเป็นข้อมูลค้าง'
           + '\ngravity: ' + fmt(d.gravity_sg, 3) + ' SG (ค้าง ไม่อัปเดตแล้ว)'
           + (d.estimated_beer_temp_c != null
               ? ('\nอุณหภูมิเบียร์: ≈' + fmt(d.estimated_beer_temp_c, 2) + '°C (ประมาณจากตู้ควบคุม)')
               : ('\nอุณหภูมิเบียร์: ประมาณไม่ได้ (Pill ค้างที่ ' + fmt(d.temperature_c, 2) + '°C)')))
        : ('\ngravity: ' + fmt(d.gravity_sg, 3) + ' SG, Pill: ' + fmt(d.temperature_c, 2) + '°C'))
    + '\nตู้ควบคุม: ' + fmt(d.controller_temp_c, 2) + '°C (target ' + fmt(d.target_temperature_c, 2) + '°C)'
    + '\nABV: ~' + fmt(d.abv_percent, 2) + '%';
  sections.push(header);

  if (d.phase_timeline_text) {
    sections.push('⏱️ ไทม์ไลน์การหมัก:\n' + d.phase_timeline_text);
  }

  sections.push(d.reasoning);

  if (d.next_phase) {
    sections.push('🔜 ใกล้เข้าเฟส ' + d.next_phase + ':\n' + d.prep_actions_text);
  }

  if (d.batch_ready_to_package) {
    sections.push('🎉 cold crash ครบช่วงแล้ว — พร้อมบรรจุ/แพ็คได้ เก็บเบียร์เสร็จแล้วสั่ง /ferment_stop เพื่อปิด batch');
  }

  if (d.recommended_controller_target_c != null) {
    let recSection = '🌡️ แนะนำตั้ง target ใหม่ ' + fmt(d.recommended_controller_target_c, 2) + '°C (ให้ Pill ถึง ' + fmt(d.recommended_pill_temp_c, 2) + '°C ตามแผน)';
    if (d.pill_eta_text) {
      recSection += '\n⏱️ ' + d.pill_eta_text;
    }
    sections.push(recSection);
  }

  const LIMIT = 1900;
  const chunks = [];
  for (const section of sections) {
    if (section.length <= LIMIT) {
      chunks.push(section);
    } else {
      for (let i = 0; i < section.length; i += LIMIT) {
        chunks.push(section.slice(i, i + LIMIT));
      }
    }
  }

  chunks.forEach((content, i) => {
    results.push({
      json: {
        content,
        is_last: i === chunks.length - 1,
        batch_id: d.batch_id,
        recommended_controller_target_c: d.recommended_controller_target_c,
        recommended_pill_temp_c: d.recommended_pill_temp_c,
        next_phase: d.next_phase
      }
    });
  });
});

return results;

// เวลาอ้างอิงสำหรับให้ sub-workflow วิเคราะห์เฟส ("Phase Analysis Engine")
// ใช้คิด hoursSinceStart และอัตราไต่อุณหภูมิ Pill ช่วง 6 ชม.ล่าสุด (ETA) — cron จริง
// ใช้เวลาปัจจุบันจริงเสมอ ต่างจาก Phase Analysis Backtest ที่ stamp เป็น cutoff
// จำลองแทน (ดู Phase Analysis Backtest.json's node เดียวกันนี้)
const items = $input.all();
return items.map((it) => ({
  json: {
    ...it.json,
    analysis_time_iso: new Date().toISOString()
  }
}));

// loop ทุก item (1 item = 1 batch active) ตามกฎ $input.all() — สร้างข้อความเตือนเฉพาะ
// sensor ที่เงียบเกิน threshold แล้วเท่านั้น ถ้าไม่มีตัวไหนเงียบ return [] (HTTP node
// ถัดไปจะไม่ยิงอะไรเลย)
// threshold 6 ชม. = ขาดข้อมูลเกิน 1 รอบ cron เต็มๆ (cron รันทุก 4 ชม. + RAPT รายงานทุก
// ~15-45 นาที) — ตั้งสูงไว้กัน false positive จากจังหวะ fetch/ลำดับ branch เพราะถึง
// sensor แค่สะดุดชั่วคราวก็ไม่ควรแจ้งเตือนพร่ำเพรื่อ
const THRESHOLD_H = 6;
const items = $input.all();
const results = [];
items.forEach((it) => {
  const d = it.json;
  const problems = [];
  if (d.pill_age_h == null) {
    problems.push('Pill "' + (d.pill_name || '-') + '" ไม่มีข้อมูลเลย');
  } else if (Number(d.pill_age_h) > THRESHOLD_H) {
    problems.push('Pill "' + (d.pill_name || '-') + '" เงียบมา ' + Number(d.pill_age_h).toFixed(1) + ' ชม.');
  }
  if (d.ctrl_age_h == null) {
    problems.push('ตู้ควบคุม "' + (d.controller_name || '-') + '" ไม่มีข้อมูลเลย');
  } else if (Number(d.ctrl_age_h) > THRESHOLD_H) {
    problems.push('ตู้ควบคุม "' + (d.controller_name || '-') + '" เงียบมา ' + Number(d.ctrl_age_h).toFixed(1) + ' ชม.');
  }
  if (problems.length) {
    results.push({
      json: {
        content: '📡 เซ็นเซอร์ไม่ส่งข้อมูล — ' + d.beer_name + ':\n• ' + problems.join('\n• ') + '\nเช็คแบต Pill / WiFi / ปลั๊กตู้ควบคุม แล้วดูใน RAPT portal ว่า device ยัง online ไหม'
      }
    });
  }
});
return results;

// กู้ item context ของ batch กลับมาหลัง Postgres INSERT — INSERT ที่ไม่มี RETURNING จะ
// ทับ $json ด้วยผลลัพธ์เปล่าและทำให้ pairedItem หลุด (บั๊กที่เคยเจอในข้อ 8.3) อ่านจาก
// $('Get Active Batches').all() ตรงๆ ปลอดภัยเพราะอ้างอิง node ด้วยชื่อ ไม่พึ่ง pairedItem
// และได้ item ครบทุก batch เรียงลำดับเดิมเสมอ
return $('Get Active Batches').all().map(it => ({ json: it.json }));

// กู้ item context ของ batch กลับมาหลัง Postgres INSERT — INSERT ที่ไม่มี RETURNING จะ
// ทับ $json ด้วยผลลัพธ์เปล่าและทำให้ pairedItem หลุด (บั๊กที่เคยเจอในข้อ 8.3) อ่านจาก
// $('Get Active Batches').all() ตรงๆ ปลอดภัยเพราะอ้างอิง node ด้วยชื่อ ไม่พึ่ง pairedItem
// และได้ item ครบทุก batch เรียงลำดับเดิมเสมอ
return $('Get Active Batches').all().map(it => ({ json: it.json }));
